const byId = new Map(EXPRESSIONS.map(row => [row.id, row]));
const recipeById = new Map(V3_RECIPES.map(row => [row.id,row]));
const interactionById = new Map(V3_INTERACTIONS.map(row => [row.id,row]));
export function getExpression(personaId, stateId) { return byId.get(`${personaId}.${stateId}`) ?? null; }
export function getExpressionById(id) { return byId.get(id) ?? null; }
export function getV3Recipe(personaId, recipeId) { return recipeById.get(`v3.${personaId}.${recipeId}`) ?? null; }
export function getV3Interaction(personaId, interactionId) { return interactionById.get(`v3.${personaId}.${interactionId}`) ?? null; }
export function listExpressions(personaId) { return EXPRESSIONS.filter(row => !personaId || row.personaId === personaId); }
